package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import java.util.zip.ZipOutputStream;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_read_TriageGen0Test {

    /**
     * Helper to create a valid ZIP byte array in memory.
     */
    private byte[] createZipWithContent(String content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("test.txt");
            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    @Test
    public void testRead_ClosedStream() throws IOException {
        byte[] zipData = createZipWithContent("hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();
        zais.close();

        byte[] buffer = new byte[10];
        try {
            zais.read(buffer, 0, 5);
            Assert.fail("Should have thrown IOException because stream is closed");
        } catch (IOException e) {
            Assert.assertEquals("The stream is closed", e.getMessage());
        }
    }

    @Test
    public void testRead_FinishedOrNullEntry() throws IOException {
        byte[] zipData = createZipWithContent("hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));

        // Case: current == null (no entry selected)
        byte[] buffer = new byte[10];
        Assert.assertEquals(-1, zais.read(buffer, 0, 5));

        // Case: inf.finished() (after reading all entries)
        zais.getNextZipEntry(); // Select first entry
        // Exhaust the stream logic via internal state is hard without reflection, 
        // but calling getNextEntry again when done should trigger finished state.
        zais.getNextZipEntry(); 
        Assert.assertEquals(-1, zais.read(buffer, 0, 5));
    }

    @Test
    public void testRead_InvalidParameters() throws IOException {
        byte[] zipData = createZipWithContent("hello");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));
        zais.getNextZipEntry();
        byte[] buffer = new byte[5];

        // start < 0
        try {
            zais.read(buffer, -1, 2);
            Assert.fail();
        } catch (ArrayIndexOutOfBoundsException e) {}

        // length < 0
        try {
            zais.read(buffer, 0, -1);
            Assert.fail();
        } catch (ArrayIndexOutOfBoundsException e) {}

        // start > buffer.length
        try {
            zais.read(buffer, 10, 1);
            Assert.fail();
        } catch (ArrayIndexOutOfBoundsException e) {}

        // buffer overflow (start + length > buffer.length)
        try {
            zais.read(buffer, 3, 3);
            Assert.fail();
        } catch (ArrayIndexOutOfBoundsException e) {}
    }

    @Test
    public void testRead_DeflatedContent() throws IOException {
        String content = "This is a test string for inflation";
        byte[] zipData = createZipWithContent(content);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(zipData));

        zais.getNextZipEntry();
        byte[] buffer = new byte[10];

        int read = zais.read(buffer, 0, 5);
        Assert.assertEquals(5, read);
        Assert.assertEquals(content.substring(0, 5), new String(buffer, 0, 5));

        int read2 = zais.read(buffer, 0, 10);
        Assert.assertTrue(read2 > 0);

        // Read until end
        int lastRead;
        while ((lastRead = zais.read(buffer, 0, buffer.length)) != -1) {
            // consuming
        }
    }

    @Test
    public void testRead_StoredContent() throws IOException {
        // To trigger STORED mode, we need to manually construct a ZIP with STORED entry
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("stored.txt");
            entry.setMethod(ZipEntry.STORED);
            // For STORED, we must provide CRC and Size
            byte[] data = "stored data".getBytes();
            CRC32 crc = new CRC32();
            crc.update(data);
            entry.setCrc(crc.getValue());
            entry.setSize(data.length);

            zos.putNextEntry(entry);
            zos.write(data);
            zos.closeEntry();
        }

        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();

        byte[] buffer = new byte[5];
        // Test partial read
        int read1 = zais.read(buffer, 0, 4);
        Assert.assertEquals(4, read1);
        Assert.assertEquals("stor", new String(buffer, 0, 4));

        // Test reading across the internal buffer boundary (triggering offsetInBuffer reset)
        // We need to read enough to trigger the (offsetInBuffer >= lengthOfLastRead) condition
        byte[] largeBuffer = new byte[20];
        int read2 = zais.read(largeBuffer, 0, 15);
        Assert.assertTrue(read2 > 0);
    }

    @Test
    public void testRead_TruncatedFile() throws IOException {
        // Create a corrupted zip where the stream ends abruptly
        byte[] zipData = createZipWithContent("some content");
        // Truncate the array mid-way
        byte[] truncated = new byte[zipData.length / 2];
        System.arraycopy(zipData, 0, truncated, 0, truncated.length);

        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(truncated));
        zais.getNextZipEntry();

        byte[] buffer = new byte[10];
        try {
            // Depending on where it's truncated, it might throw IOException for "Truncated ZIP file"
            // or just return -1 if the inflater finishes.
            zais.read(buffer, 0, 10);
        } catch (IOException e) {
            // This is an acceptable outcome for a corrupted file
        }
    }
}
